args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?filmLater ?filmLaterLabel ?bdLater ?filmOther ?filmOtherLabel ?bdOther WHERE {
  VALUES (?f1 ?f2) {
    (dbr:Hum_Dil_De_Chuke_Sanam dbr:The_Greyhound_Limited)
    (dbr:The_Greyhound_Limited dbr:Hum_Dil_De_Chuke_Sanam)
  }
  ?f1 dbp:director ?d1 .
  ?f2 dbp:director ?d2 .
  OPTIONAL { ?d1 dbo:birthDate ?bd1. }
  OPTIONAL { ?d1 dbp:birthDate ?bd1b. }
  OPTIONAL { ?d2 dbo:birthDate ?bd2. }
  OPTIONAL { ?d2 dbp:birthDate ?bd2b. }
  BIND(coalesce(?bd1, ?bd1b) AS ?bd1f)
  BIND(coalesce(?bd2, ?bd2b) AS ?bd2f)
  FILTER(bound(?bd1f) && bound(?bd2f))
  FILTER(?bd1f > ?bd2f)
  BIND(?f1 AS ?filmLater)
  BIND(?bd1f AS ?bdLater)
  BIND(?f2 AS ?filmOther)
  BIND(?bd2f AS ?bdOther)
  OPTIONAL { ?filmLater rdfs:label ?filmLaterLabel FILTER(lang(?filmLaterLabel) = "en") }
  OPTIONAL { ?filmOther rdfs:label ?filmOtherLabel FILTER(lang(?filmOtherLabel) = "en") }
}
LIMIT 10

